"use client";

import * as React from "react";
import { Tooltip as TooltipPrimitive } from "@base-ui/react/tooltip";

import { cn } from "@/lib/utils";
import { popupMotion } from "./_shared";

// Base UI accepts a state function for className; these wrappers merge it with
// cn(), so they take a plain string.
type WithClassName<P> = Omit<P, "className"> & { className?: string };

/** Shares the open and close delay across every tooltip inside it. */
const TooltipProvider = TooltipPrimitive.Provider;

/** Bold retail Tooltip root: a short label for one control. */
const Tooltip = TooltipPrimitive.Root;

/** The control the tooltip describes. */
const TooltipTrigger = TooltipPrimitive.Trigger;

/**
 * Bold retail tooltip: a black chip with white medium text and a 0.5rem
 * corner, no arrow and no shadow. The black alone lifts it off the white
 * page. It settles from the control as it fades in.
 */
const TooltipContent = React.forwardRef<
  HTMLDivElement,
  WithClassName<TooltipPrimitive.Popup.Props> &
    Pick<
      TooltipPrimitive.Positioner.Props,
      "align" | "alignOffset" | "side" | "sideOffset"
    >
>(({ className, align, alignOffset, side, sideOffset = 6, ...props }, ref) => (
  <TooltipPrimitive.Portal>
    <TooltipPrimitive.Positioner
      align={align}
      alignOffset={alignOffset}
      side={side}
      sideOffset={sideOffset}
      className="isolate z-50"
    >
      <TooltipPrimitive.Popup
        ref={ref}
        data-slot="tooltip-content"
        className={cn(
          popupMotion,
          "max-w-64 rounded-md bg-primary px-2.5 py-1.5 text-xs font-medium leading-snug text-primary-foreground",
          className,
        )}
        {...props}
      />
    </TooltipPrimitive.Positioner>
  </TooltipPrimitive.Portal>
));
TooltipContent.displayName = "TooltipContent";

export { Tooltip, TooltipTrigger, TooltipContent, TooltipProvider };
